import { type } from "arktype";

/**
 * `State` is a discriminated union keyed on the literal `status` field.
 *
 * Each branch is defined as a plain object Type (no morphs) so that ArkType
 * can resolve the union deterministically via the `status` literal discriminator.
 *
 * Branches:
 *  - Idle    : { status: "idle" }
 *  - Loading : { status: "loading",  startedAt: integer >= 0 }
 *  - Success : { status: "success",  data: unknown, fetchedAt: integer >= 0 }
 *  - Failure : { status: "failure",  code: integer in [400, 599], reason: string len 1..200 }
 */
export const State = type({
    status: '"idle"',
})
    .or({
        status: '"loading"',
        startedAt: type.number.integer.atLeast(0),
    })
    .or({
        status: '"success"',
        data: "unknown",
        fetchedAt: type.number.integer.atLeast(0),
    })
    .or({
        status: '"failure"',
        code: type.number.integer.atLeast(400).atMost(599),
        reason: type.string.atLeastLength(1).atMostLength(200),
    });

export type State = typeof State.infer;

/**
 * `Event` is a discriminated union keyed on the literal `type` field.
 *
 * Branches:
 *  - Start  : { type: "start",   at: number }
 *  - Resolve: { type: "resolve", data: unknown, at: number }
 *  - Reject : { type: "reject",  code: integer, reason: string, at: number }
 *  - Reset  : { type: "reset" }
 */
export const Event = type({
    type: '"start"',
    at: "number",
})
    .or({
        type: '"resolve"',
        data: "unknown",
        at: "number",
    })
    .or({
        type: '"reject"',
        code: type.number.integer,
        reason: "string",
        at: "number",
    })
    .or({
        type: '"reset"',
    });

export type Event = typeof Event.infer;

/** Truncate a number to an integer (towards zero), as required by the rules. */
const truncInt = (n: number): number => Math.trunc(n);

/**
 * The core transition logic, expressed as a pure (un-validated) function.
 *
 * Only the listed state/event pairings change the state; every other
 * combination leaves the state unchanged.
 */
function applyTransition(state: State, event: Event): State {
    // Reset wins from any state.
    if (event.type === "reset") {
        return { status: "idle" };
    }

    if (state.status === "idle" && event.type === "start") {
        return { status: "loading", startedAt: truncInt(event.at) };
    }

    if (state.status === "loading" && event.type === "resolve") {
        return {
            status: "success",
            data: event.data,
            fetchedAt: truncInt(event.at),
        };
    }

    if (state.status === "loading" && event.type === "reject") {
        return {
            status: "failure",
            code: event.code,
            reason: event.reason,
        };
    }

    // No matching rule: state is unchanged.
    return state;
}

/**
 * `transition` is a runtime-validated function.
 *
 * `type.fn(State, Event, ":", State)` wraps `applyTransition` so that:
 *  - the first parameter  is validated against `State`,
 *  - the second parameter is validated against `Event`,
 *  - the returned value   is validated against `State`.
 *
 * Any validation failure (invalid input state, invalid event, or an invalid
 * state produced by the transition logic) throws an `ArkErrors`-style
 * `TraversalError` at the boundary.
 */
export const transition = type.fn(State, Event, ":", State)(applyTransition);

import { ArkErrors, type } from "arktype";
import { State, transition } from "./src/statemachine.js";

/**
 * CLI entrypoint.
 *
 * Reads a single JSON document from stdin with the shape:
 *   { "initial": <State>, "events": [<Event>, ...] }
 *
 * Replays the events through `transition` in order and prints the outcome:
 *   - On success:   first non-empty line is `VALID`, followed by a
 *                    JSON-stringified final `State`.
 *   - On failure:    a single non-empty line beginning with `INVALID: `.
 *
 * Always exits with code 0, even when the input is rejected.
 */

/** Describe any error value as a single-line string for the INVALID output. */
function describeError(error: unknown): string {
    if (error instanceof ArkErrors) {
        return error.summary;
    }
    // `type.fn` throws a `TraversalError` which carries `ArkErrors` and whose
    // `message` is the ArkErrors summary.
    if (error instanceof Error && "arkErrors" in error && error.arkErrors instanceof ArkErrors) {
        return (error.arkErrors as ArkErrors).summary;
    }
    if (error instanceof Error) {
        return error.message;
    }
    return String(error);
}

/** Read all of stdin as a single string. */
function readStdin(): Promise<string> {
    return new Promise((resolve) => {
        let data = "";
        process.stdin.setEncoding("utf8");
        process.stdin.on("data", (chunk) => {
            data += chunk;
        });
        process.stdin.on("end", () => resolve(data));
    });
}

async function main(): Promise<void> {
    const input = await readStdin();

    // Parse the envelope JSON document.
    let envelope: unknown;
    try {
        envelope = JSON.parse(input);
    } catch (error) {
        process.stdout.write(`INVALID: malformed JSON input: ${describeError(error)}\n`);
        return;
    }

    // Validate the envelope shape { initial, events }.
    if (
        typeof envelope !== "object" ||
        envelope === null ||
        Array.isArray(envelope)
    ) {
        process.stdout.write(
            "INVALID: input must be a JSON object with \"initial\" and \"events\" fields\n",
        );
        return;
    }

    const { initial, events } = envelope as Record<string, unknown>;

    if (!Array.isArray(events)) {
        process.stdout.write(
            "INVALID: \"events\" must be an array of events\n",
        );
        return;
    }

    // Validate the initial state against `State` (non-throwing).
    const initialValidated = State(initial);
    if (initialValidated instanceof type.errors) {
        process.stdout.write(
            `INVALID: initial state: ${initialValidated.summary}\n`,
        );
        return;
    }

    // Replay events through the runtime-validated transition function.
    let current = initialValidated;
    for (let i = 0; i < events.length; i++) {
        try {
            // `transition` validates both the state and the event, and
            // validates its returned state. Any failure throws here.
            current = transition(current, events[i]);
        } catch (error) {
            process.stdout.write(
                `INVALID: event ${i}: ${describeError(error)}\n`,
            );
            return;
        }
    }

    // Success.
    process.stdout.write("VALID\n");
    process.stdout.write(`${JSON.stringify(current)}\n`);
}

main().catch((error) => {
    // Should not happen, but never crash: report as INVALID and exit 0.
    process.stdout.write(`INVALID: unexpected error: ${describeError(error)}\n`);
});

